import{_ as t,K as n,a as p,c as l,ac as i,q as r}from"./chunks/framework.BSuaGltH.js";const I=JSON.parse('{"title":"计算机网络原理（04735） · 应用层：从域名到服务至协议参考","description":"按分层、链路、IP路由、传输与应用学习，配合子网/分片计算和连接流程图。","frontmatter":{"title":"计算机网络原理（04735） · 应用层：从域名到服务至协议参考","description":"按分层、链路、IP路由、传输与应用学习，配合子网/分片计算和连接流程图。","splitFrom":"principles/network-principles/internetprinciples.md","showdocs":{"topics":[{"id":"network-principles","title":"计算机网络原理","link":"/topics/network-principles/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"故障边界与规范","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"计算机网络原理（04735）","summary":"按分层、链路、IP路由、传输与应用学习，配合子网/分片计算和连接流程图。","status":"active","related":[{"title":"计算机网络原理（04735）","link":"/principles/network-principles/internetprinciples","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"计算机网络原理（04735） · 先建立分层与交换的整体认识至物理与链路：先让相邻节点通信","link":"/principles/network-principles/internetprinciples-part-01","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接","link":"/principles/network-principles/internetprinciples-part-02","kind":"故障边界与规范","scope":"general","audience":"general"},{"title":"长度前缀分帧与粘包拆包练习","link":"/principles/network-principles/application","kind":"应用分帧推演","scope":"general","audience":"general"},{"title":"TCP字节流、可靠传输与网络排错","link":"/principles/network-principles/tcp-and-network-diagnosis","kind":"层次与端到端机制","scope":"general","audience":"general"}],"prev":{"text":"计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接","link":"/principles/network-principles/internetprinciples-part-02"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"计算机网络原理（04735） · IP、子网与路由：跨网络送达主机至传输层：端口、可靠交付与连接","link":"/principles/network-principles/internetprinciples-part-02"},"next":false},"headers":[],"relativePath":"principles/network-principles/internetprinciples-part-03.md","filePath":"principles/network-principles/internetprinciples-part-03.md"}'),o={name:"principles/network-principles/internetprinciples-part-03.md"};function d(s,e,c,h,u,P){const a=n("Mermaid");return p(),l("div",null,[e[0]||(e[0]=i('<h1 id="计算机网络原理-04735-·-应用层-从域名到服务至协议参考" tabindex="-1">计算机网络原理（04735） · 应用层：从域名到服务至协议参考 <a class="header-anchor" href="#计算机网络原理-04735-·-应用层-从域名到服务至协议参考" aria-label="Permalink to &quot;计算机网络原理（04735） · 应用层：从域名到服务至协议参考&quot;">​</a></h1><p><a href="/principles/network-principles/internetprinciples">返回分篇目录</a></p><p>按“分层与性能 → 链路 → IP 与路由 → 传输 → 应用”的顺序理解一次请求，再补充无线与安全。历史课程中的电路交换、PPP、经典共享以太网等保留为原理对照，不与现代网络部署混写。</p><h2 id="applications" tabindex="-1">应用层：从域名到服务 <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;应用层：从域名到服务 {#applications}&quot;">​</a></h2><h3 id="dns-查询与缓存" tabindex="-1">DNS 查询与缓存 <a class="header-anchor" href="#dns-查询与缓存" aria-label="Permalink to &quot;DNS 查询与缓存 {#dns-查询与缓存}&quot;">​</a></h3><p>下图假设递归解析器没有可用缓存。根和顶级域服务器通常返回委派线索，解析器继续查询权威服务器，最后缓存答案；后续查询在TTL允许范围内可直接使用缓存。</p>',6)),r(a,{source:""}),e[1]||(e[1]=i('<p>DNS 按分布式层级管理名字和资源记录。主机通常向递归解析器查询，解析器在缓存未命中时向根、顶级域和权威服务器等逐步取得信息；有缓存或已有委派信息时，无需每次从根开始。</p><p>DNS 不只返回 IP，常见记录有 A、AAAA、CNAME、MX 等。域名从右向左形成层级；例如 <code>www.example.com</code> 的顶级域是 <code>com</code>，不能把多标签的 <code>com.cn</code> 与独立顶级域混淆。</p><h3 id="http、连接与状态码" tabindex="-1">HTTP、连接与状态码 <a class="header-anchor" href="#http、连接与状态码" aria-label="Permalink to &quot;HTTP、连接与状态码 {#http、连接与状态码}&quot;">​</a></h3><p>HTTP 定义请求方法、字段、状态码与内容语义。HTTP/1.1 使用文本形式的起始行与首部，HTTP/2 使用二进制帧，HTTP/3 基于 QUIC；不能把所有 HTTP 都说成先建立 TCP。</p><p>GET 读取资源表示，HEAD 获取类似 GET 的首部而不返回内容，POST 提交处理，PUT 更新目标资源表示，OPTIONS 查询通信选项。持久连接减少重复建连，实际往返次数取决于协议、对象数、缓存和并发，不能孤立记成固定 3/4/8 RTT。</p><table tabindex="0"><thead><tr><th>类别 / 状态</th><th>含义</th></tr></thead><tbody><tr><td>1xx / 2xx / 3xx</td><td>信息性 / 成功 / 重定向相关</td></tr><tr><td>4xx / 5xx</td><td>客户端错误 / 服务端错误</td></tr><tr><td>200 / 301 / 304</td><td>成功 / 永久重定向 / 缓存表示未修改</td></tr><tr><td>400 / 401 / 403 / 404</td><td>请求无效 / 需认证 / 禁止 / 未找到</td></tr><tr><td>415</td><td>不支持的媒体类型，不是 451</td></tr><tr><td>500 / 502 / 503</td><td>服务端错误 / 网关上游错误 / 暂不可用</td></tr></tbody></table><p>HTTP 无状态不等于服务器无法保存会话。Cookie 由响应 <code>Set-Cookie</code> 设置、浏览器按作用域通过 <code>Cookie</code> 发送，可用于会话标识与偏好；不应直接保存明文密码。会话 Cookie 的恢复行为受浏览器会话恢复等机制影响，不能一概说关闭窗口就彻底清除。</p><h3 id="邮件、文件传输与-socket" tabindex="-1">邮件、文件传输与 Socket <a class="header-anchor" href="#邮件、文件传输与-socket" aria-label="Permalink to &quot;邮件、文件传输与 Socket {#邮件、文件传输与-socket}&quot;">​</a></h3><p>SMTP 负责邮件提交/传输，POP3、IMAP 用于收取与管理；MIME 表达附件和多媒体。端口、TLS 与认证取决于具体服务模式，不把所有邮件连接都固定为明文 25/110。</p><p>FTP 把控制与数据连接分开，控制常用 21；主动与被动模式的数据连接不同，不能断言数据永远走 20。P2P 中节点可兼有请求与服务角色，实际应用也可能依赖中心协调。</p><p>Socket 是应用使用网络能力的接口。TCP 服务端常见顺序为 <code>socket → bind → listen → accept → 收发 → close</code>，客户端为 <code>socket → connect → 收发 → close</code>；UDP 常用 <code>sendto/recvfrom</code>。一次 <code>send/recv</code> 不保证刚好对应一个应用消息。</p><p><span id="第七章无线与移动网络" aria-hidden="true"></span><span id="_1-无线网络" aria-hidden="true"></span><span id="_2-移动网络" aria-hidden="true"></span><span id="_3-无线局域网-ieee802-11" aria-hidden="true"></span><span id="_4-蜂窝网络" aria-hidden="true"></span><span id="_5-移动-ip-网络" aria-hidden="true"></span><span id="_6-其他典型无线网络简介" aria-hidden="true"></span><span id="小结" aria-hidden="true"></span></p><h2 id="wireless" tabindex="-1">无线、移动性与切换 <a class="header-anchor" href="#wireless" aria-label="Permalink to &quot;无线、移动性与切换 {#wireless}&quot;">​</a></h2><p>终端从AP1转到AP2后，先判断二层接入是否完成，再判断IP是否变化。保持相同IP也不能保证没有短时丢包；IP变化后原有传输连接能否继续，取决于协议和部署支持。</p>',14)),r(a,{source:"Zmxvd2NoYXJ0IExSCiBBWyLnu4jnq6/ov57mjqVBUDEiXSAtLT4gQlsi6YeN5YWz6IGUQVAyIl0KIEIgLS0+IEN7IklQ5Y+K6Lev5b6E5piv5ZCm5Y+Y5YyW77yfIn0KIEMgLS0gIuS4jeWPmCIgLS0+IERbIuajgOafpeS4ouWMheWSjOi/nuaOpeaBouWkjSJdCiBDIC0tICLlj5jljJYiIC0tPiBFWyLmjInljY/orq7ov4Hnp7vmiJblupTnlKjph43ov54iXQo="}),e[2]||(e[2]=i('<p>无线链路要处理衰减、干扰、多径和隐藏终端等问题。IEEE 802.11 的 AP 与终端组成基本服务集，帧包含管理、控制、数据等类型；无线接入并不意味着设备正在移动。</p><p>移动性涉及位置、可达地址与连接连续性。传统 Mobile IP 用归属网络、归属代理和转交地址等机制说明“位置变化而维持标识”的思路；它不等于所有现代蜂窝或 Wi-Fi 漫游的具体实现。切换时要区分链路重关联、IP 变化和应用重连。</p><p><span id="第八章网络安全基础" aria-hidden="true"></span><span id="_1-网络安全概述" aria-hidden="true"></span><span id="_2-数据加密" aria-hidden="true"></span><span id="_3-消息完整性与数字签名" aria-hidden="true"></span><span id="_4-身份验证" aria-hidden="true"></span><span id="_5-密钥分发中心与证书认证" aria-hidden="true"></span><span id="_6-防火墙与入侵检测系统" aria-hidden="true"></span><span id="防火墙" aria-hidden="true"></span><span id="_7-网络安全协议" aria-hidden="true"></span><span id="电子邮件对网络安全的需求" aria-hidden="true"></span><span id="ssl-tls" aria-hidden="true"></span><span id="ipsec" aria-hidden="true"></span></p><h2 id="security" tabindex="-1">安全：加密、认证与网络边界 <a class="header-anchor" href="#security" aria-label="Permalink to &quot;安全：加密、认证与网络边界 {#security}&quot;">​</a></h2><h3 id="机密性、完整性与身份" tabindex="-1">机密性、完整性与身份 <a class="header-anchor" href="#机密性、完整性与身份" aria-label="Permalink to &quot;机密性、完整性与身份 {#机密性、完整性与身份}&quot;">​</a></h3><p>安全目标应分别验证。加密隐藏内容，消息认证验证内容和持有密钥的一方，证书验证则帮助绑定公钥与预期身份；其中任一成功都不能自动证明业务授权正确。</p>',6)),r(a,{source:"Zmxvd2NoYXJ0IFRECiBBWyLmlLbliLDlj5fkv53miqTmtojmga8iXSAtLT4gQlsi6aqM6K+B6Lqr5Lu95LiO5a+G6ZKl5p2l5rqQIl0KIEIgLS0+IENbIumqjOivgeWujOaVtOaAp+W5tuino+WvhiJdCiBDIC0tPiBEWyLlupTnlKjmo4Dmn6XmnYPpmZDkuI7kuJrliqHnirbmgIEiXQogRCAtLT4gRVsi5YWB6K645a+55bqU5pON5L2cIl0K"}),e[3]||(e[3]=i('<p>对称加密用于共享密钥下的数据保护；公钥机制可用于身份认证、密钥协商或签名，具体算法用途不同。哈希本身不证明消息来自可信发送方，MAC 依赖共享秘密，数字签名结合私钥签名与公钥验证。</p><p>证书把公钥与身份联系起来，验证还包括信任链、有效期及目标名称等条件。历史课程提到 DES、MD5、SSL 等，不应直接作为现代安全配置建议。</p><h3 id="tls、ipsec-与防火墙" tabindex="-1">TLS、IPsec 与防火墙 <a class="header-anchor" href="#tls、ipsec-与防火墙" aria-label="Permalink to &quot;TLS、IPsec 与防火墙 {#tls、ipsec-与防火墙}&quot;">​</a></h3><p>TLS 提供传输保护，握手、密钥派生和认证流程因版本而异；旧 RSA 预主密钥流程不能代替 TLS 1.3 的协商机制。具体细节按协议版本学习。</p><p>IPsec 是网络层安全体系，包含 ESP/AH 等协议与传输/隧道模式；VPN 的实现和安全性取决于选定协议、配置与密钥管理，不能用“某个名字最安全”作结论。</p><p>防火墙可按无状态规则、连接状态或应用代理等方式过滤流量；检测系统用来发现异常。允许端口不代表应用已经有正确的鉴权，启用加密也不代表所有授权问题都已解决。</p><h2 id="practice" tabindex="-1">用一次请求串联复习 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;用一次请求串联复习 {#practice}&quot;">​</a></h2><ol><li>画出客户端、AP/交换机、网关、路由器和服务端，标出每跳 MAC 与端到端 IP。</li><li>给定地址和掩码计算子网，按最长前缀选择下一跳。</li><li>解释 DNS 命中/未命中、TCP 或 QUIC 建连、TLS 与 HTTP 各自做什么。</li><li>区分 DNS 失败、连接失败、认证失败、上游超时和吞吐瓶颈，不把所有问题归为“网络不好”。</li><li>用一份抓包核对序号、确认和重传，用实际时延数据区分排队、传播与发送开销。</li></ol><h2 id="协议参考" tabindex="-1">协议参考 <a class="header-anchor" href="#协议参考" aria-label="Permalink to &quot;协议参考 {#协议参考}&quot;">​</a></h2><ul><li><a href="https://www.rfc-editor.org/rfc/rfc9293.html" target="_blank" rel="noopener noreferrer">TCP：RFC 9293</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc1034.html" target="_blank" rel="noopener noreferrer">DNS：RFC 1034</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9114.html" target="_blank" rel="noopener noreferrer">HTTP/3：RFC 9114</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc8446.html" target="_blank" rel="noopener noreferrer">TLS 1.3：RFC 8446</a></li></ul>',10))])}const _=t(o,[["render",d]]);export{I as __pageData,_ as default};
